+// NAV-1 · Overview answers the question first. The landing screen states, from the data: rules built / total, tests
+// passing, nodes done, attempts and FAILs taken, human decisions recorded; each figure links to its source. And, from
+// docs/trace/ui/DS/g4-defects.md section 3 (U1's acceptance): the overview draws the search and the theme toggle once.
+// On the `rules` fixture trail (its README lists every figure below); parity on the design fixture against
+// docs/ui/derived/U1/overview/.
+import { expect, test } from '@playwright/test';
+import { REPO, auditEverywhere, compileRules, openOnFixture, region, route } from './support/app';
+import type { CompiledTrail } from './support/app';
+import { expectRegionComponents, expectRegionsInOrder, expectShell, expectTokensOnly, overview } from './support/parity';
+
+const HEADLINE = 'headline-answer';
+const FIGURES = 'receipt-figures-rules-built-total-tests-passing-nodes-done-attempts-and-fails-human-decisions';
+const GITHUB_DOC = (path: string): RegExp =>
+  new RegExp(`^${REPO.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}/(blob|tree)/[^/]+/${path}`);
+
+let fixture: CompiledTrail;
+test.beforeAll(() => {
+  fixture = compileRules();
+});
+test.afterAll(() => {
+  fixture?.trail.cleanup();
+});
+
+test.describe('the question first', () => {
+  test('NAV-1 · the overview opens on the question, before any other region', async ({ page }) => {
+    await openOnFixture(page, fixture, route.overview);
+    const main = page.getByRole('main');
+    await expect(main.locator('[data-region]').first(), 'the headline answer is the first region').toHaveAttribute('data-region', HEADLINE);
+    const headline = region(page, HEADLINE);
+    await expect(headline.getByRole('heading', { level: 1 })).toHaveText('Overview');
+    await expect(headline).toContainText('Was this really test-driven, and was the AI really checked?');
+    // The answer is the fixture's, not the design fixture's (29 rules, 51 verdicts).
+    await expect(headline).toContainText('3 of 5');
+  });
+
+  test("NAV-1 · the answer states, from the fixture, that 3 of 5 rules list a red commit and 1 of 4 verdicts was FAIL", async ({ page }) => {
+    await openOnFixture(page, fixture, route.overview);
+    const headline = region(page, HEADLINE);
+    await expect(headline).toContainText(/3 of 5 rules/);
+    await expect(headline).toContainText(/1 of 4\b[^.]*FAIL/);
+    for (const foreign of ['29 of 29', '9 of 51', 'b394466']) await expect(headline, `"${foreign}" is not in the fixture`).not.toContainText(foreign);
+  });
+});
+
+// rules/README.md, "Receipt figures", in NAV-1's own order.
+const figures = [
+  { name: 'rules built', value: '3 of 5', unit: /rules built/i, label: /docs\/trace\/requirements-matrix\.md/, href: GITHUB_DOC('docs/trace/requirements-matrix\\.md') },
+  { name: 'tests passing', value: '2 of 5', unit: /test/i, label: /docs\/trace\/requirements-matrix\.md/, href: GITHUB_DOC('docs/trace/requirements-matrix\\.md') },
+  { name: 'nodes done', value: '2 of 4', unit: /nodes done/i, label: /docs\/plans\/active\/build\.dag\.yaml/, href: GITHUB_DOC('docs/plans/active/build\\.dag\\.yaml') },
+  { name: 'attempts taken', value: '1 of 2', unit: /attempt/i, label: /docs\/plans\/active\/build\.dag\.yaml/, href: GITHUB_DOC('docs/plans/active/build\\.dag\\.yaml') },
+  { name: 'FAILs taken', value: '1 of 4', unit: /FAIL/, label: /docs\/trace\/build\/.*verdicts/, href: GITHUB_DOC('docs/trace/build') },
+  { name: 'human decisions recorded', value: '2', unit: /human decisions/i, label: /docs\/trace\/build\/.*loop\.jsonl/, href: GITHUB_DOC('docs/trace/build') },
+] as const;
+
+test.describe('the receipt figures', () => {
+  test('NAV-1 · the overview shows six receipt figures, in the order the rule names them', async ({ page }) => {
+    await openOnFixture(page, fixture, route.overview);
+    const shown = region(page, FIGURES).locator('figure');
+    await expect(shown).toHaveCount(figures.length);
+    for (const [i, f] of figures.entries()) await expect(shown.nth(i).locator('figcaption'), `figure ${i + 1} is ${f.name}`).toContainText(f.unit);
+  });
+
+  for (const [i, f] of figures.entries()) {
+    test(`NAV-1 · receipt figure ${i + 1}, ${f.name}, reads ${f.value} from the fixture`, async ({ page }) => {
+      await openOnFixture(page, fixture, route.overview);
+      const figure = region(page, FIGURES).locator('figure').nth(i);
+      await expect(figure.locator('figcaption'), `figure ${i + 1} is ${f.name}`).toContainText(f.unit);
+      await expect(figure.locator('p').first()).toHaveText(f.value);
+    });
+
+    test(`NAV-1 · receipt figure ${i + 1}, ${f.name}, links to the source it was counted from`, async ({ page }) => {
+      await openOnFixture(page, fixture, route.overview);
+      const figure = region(page, FIGURES).locator('figure').nth(i);
+      await expect(figure.locator('p').first(), 'the figure is the fixture count').toHaveText(f.value);
+      const source = figure.locator('figcaption a');
+      await expect(source).toHaveCount(1);
+      await expect(source).toContainText(f.label);
+      await expect(source).toHaveAttribute('href', f.href);
+    });
+  }
+});
+
+test.describe('the global controls', () => {
+  test('NAV-1 · the overview draws the search and the theme toggle once, in the top bar', async ({ page }) => {
+    await openOnFixture(page, fixture, route.overview);
+    await expect(region(page, FIGURES).locator('figure').first().locator('p').first(), 'the overview shows the fixture').toHaveText('3 of 5');
+    await expect(page.getByRole('search'), 'one search on the page').toHaveCount(1);
+    await expect(page.getByRole('radiogroup', { name: 'Theme' }), 'one theme toggle on the page').toHaveCount(1);
+    await expect(page.getByRole('banner').getByRole('search'), 'the search is the top bar one').toHaveCount(1);
+    await expect(page.getByRole('banner').getByRole('radiogroup', { name: 'Theme' }), 'the toggle is the top bar one').toHaveCount(1);
+  });
+});
+
+test.describe('axe', () => {
+  test('NAV-1 · the overview on the fixture has no axe violation, light and dark, at 1440 and 390', async ({ page }) => {
+    await openOnFixture(page, fixture, route.overview);
+    await auditEverywhere(page, route.overview, async (p) => {
+      await expect(region(p, FIGURES).locator('figure').first().locator('p').first()).toHaveText('3 of 5');
+    });
+  });
+});
+
+test.describe('parity', () => {
+  test("NAV-1 · parity: the overview keeps its reference's regions in order, the unbuilt ones as not built yet", async ({ page }) => {
+    await expectRegionsInOrder(page, overview);
+  });
+
+  test("NAV-1 · parity: the overview's headline answer region carries its reference's components", async ({ page }) => {
+    await expectRegionComponents(page, overview, HEADLINE);
+  });
+
+  test("NAV-1 · parity: the overview's receipt figures region carries its reference's components", async ({ page }) => {
+    await expectRegionComponents(page, overview, FIGURES);
+  });
+
+  test("NAV-1 · parity: the overview's shell, primary nav, current item and title are its reference's", async ({ page }) => {
+    await expectShell(page, overview);
+  });
+
+  test('NAV-1 · parity: the overview takes every colour from a token, light and dark', async ({ page }) => {
+    await expectTokensOnly(page, overview);
+  });
+});
diff --git a/tests/web/e2e/U1/support/app.ts b/tests/web/e2e/U1/support/app.ts
new file mode 100644
index 00000000..3b79f281
--- /dev/null
+++ b/tests/web/e2e/U1/support/app.ts
@@ -0,0 +1,188 @@
+// U1's routes and the `rules` fixture trail (tests/web/fixtures/trails/rules/README.md), on top of U0b's helpers for
+// the built app (vite preview on DOCKET_APP_PORT): serving trace data, themes, widths, axe and the footer stamp.
+import { readFileSync } from 'node:fs';
+import { join } from 'node:path';
+import { expect } from '@playwright/test';
+import type { Locator, Page } from '@playwright/test';
+import { axeViolations, backgroundToken, serveTrace, setTheme, snapshotOf, themes, tokenBackground, viewports } from '../../U0b/support/app';
+import { compileFixture, fixturesDir } from '../../U0b/support/trail';
+import type { CompiledTrail } from '../../U0b/support/trail';
+
+export {
+  PLACEHOLDER,
+  REPO,
+  axeViolations,
+  expectFooterStamp,
+  recordRequests,
+  serveTrace,
+  setTheme,
+  snapshotOf,
+  themes,
+  viewports,
+} from '../../U0b/support/app';
+export type { Theme } from '../../U0b/support/app';
+export type { CompiledTrail } from '../../U0b/support/trail';
+
+/** U1's routes (hash routing): the overview, the matrix, a rule, a node (its completeness banner) and a commit. */
+export const route = {
+  overview: '/#/',
+  matrix: '/#/rules',
+  rule: (id: string): string => `/#/rules/${id}`,
+  node: (plan: string, node: string): string => `/#/plans/${plan}/${node}`,
+  commit: (sha: string): string => `/#/commits/${sha}`,
+};
+
+/** The fixture this node's behaviour tests run on. */
+export const FIXTURE = 'rules';
+export const fixtureDir = join(fixturesDir, FIXTURE);
+
+/** Compiles the `rules` fixture once for a spec file. */
+export function compileRules(): CompiledTrail {
+  return compileFixture(FIXTURE);
+}
+
+/** A fixture commit's full SHA, by its id in rules/commits.json. Fails, as an assertion, on an unknown id. */
+export function shaOf(fixture: CompiledTrail, id: string): string {
+  const sha = fixture.trail.shas[id];
+  expect(sha, `the fixture made commit ${id}`).toMatch(/^[0-9a-f]{40}$/);
+  return sha ?? '';
+}
+
+export const short = (sha: string): string => sha.slice(0, 7);
+
+/** The 1-based line of `docs/requirements.md` (in the fixture's base) holding a rule's row. */
+export function requirementsLine(id: string): number {
+  return lineOf(join(fixtureDir, 'base', 'docs', 'requirements.md'), `| ${id} |`);
+}
+
+/** The 1-based line of the fixture's `docs/trace/requirements-matrix.md` holding a rule's row. */
+export function matrixLine(id: string): number {
+  return lineOf(join(fixtureDir, 'trail', 'docs', 'trace', 'requirements-matrix.md'), `| ${id} |`);
+}
+
+function lineOf(file: string, prefix: string): number {
+  const index = readFileSync(file, 'utf8').split(/\r?\n/).findIndex((line) => line.startsWith(prefix));
+  expect(index, `${file} has a line starting "${prefix}"`).toBeGreaterThanOrEqual(0);
+  return index + 1;
+}
+
+/**
+ * Opens a route on the compiled fixture. Asserts first that the compiler wrote a stamped trace.json for it (so a
+ * compile failure reads as one); each test then asserts the fixture's own data on the page.
+ */
+export async function openOnFixture(page: Page, fixture: CompiledTrail, path: string): Promise<void> {
+  snapshotOf(fixture.compiled);
+  await serveTrace(page, fixture.compiled.publicDir);
+  await page.goto(path);
+}
+
+/** A region of the page's main content, by its data-region slug. */
+export function region(page: Page, slug: string): Locator {
+  return page.getByRole('main').locator(`[data-region="${slug}"]`);
+}
+
+/** The rule page's regions (docs/ui/derived/U1/rule/screen.json). */
+export const RULE_TEXT = 'rule-text-and-agreed-interpretation';
+export const SIGNATURE = 'signature-red-before-green-evidence-custody-chain-tdd-ticks-chronology-per-style';
+export const TESTS = 'tests-count-and-scope';
+export const QA = 'qa-step-and-sign-off';
+export const RULE_LINKS = 'links-out-commit-shas-pr-numbers-and-file-line-references-to-github-at-that-sha';
+
+/** Opens a rule page on the fixture and waits until its heading names the rule. */
+export async function openRule(page: Page, fixture: CompiledTrail, id: string): Promise<void> {
+  await openOnFixture(page, fixture, route.rule(id));
+  await expect(page.getByRole('heading', { level: 1 }), `the page heads rule ${id}`).toContainText(id);
+}
+
+/**
+ * The commit rungs of the rule page's spine (the kit's rung-spine: a commit's rung is marked with its walkthrough row,
+ * "#2"; the rule, QA, sign-off and PR rungs are not), in page order, each as the id of the fixture commit whose short
+ * SHA it shows.
+ */
+export async function rungCommits(page: Page, fixture: CompiledTrail): Promise<string[]> {
+  const texts = await region(page, SIGNATURE)
+    .locator('li[data-kind="rung"]')
+    .evaluateAll((rungs) =>
+      rungs
+        .filter((rung) => /#\d+/.test(rung.querySelector('[data-marker]')?.textContent ?? ''))
+        .map((rung) => rung.textContent ?? ''),
+    );
+  const commits = Object.entries(fixture.trail.shas);
+  return texts.flatMap((text) => {
+    const hit = commits.find(([, sha]) => text.includes(short(sha)));
+    return hit ? [hit[0]] : [];
+  });
+}
+
+/** The commit rung of the rule page's spine that shows a commit: the rung marked with a walkthrough row. */
+export function rungOf(page: Page, sha: string): Locator {
+  return region(page, SIGNATURE)
+    .locator('li[data-kind="rung"]')
+    .filter({ has: page.locator('[data-marker]', { hasText: /#\d+/ }) })
+    .filter({ hasText: short(sha) });
+}
+
+/** The kit's rule chip, wherever it is drawn. */
+export const CHIP = 'a[class*="kit-rule-chip__chip"]';
+
+/** The kit's completeness banner. */
+export function banners(scope: Page | Locator): Locator {
+  return scope.locator('section[aria-label="Trail completeness"]');
+}
+
+/** A commit link out to GitHub for this SHA: the full SHA or its short form, as GitHub accepts both. */
+export function commitHref(repo: string, sha: string): RegExp {
+  return new RegExp(`^${repo.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}/commit/${short(sha)}[0-9a-f]{0,33}$`);
+}
+
+/**
+ * Opens `path` fresh in each theme at 1440 and 390, waits for `ready`, and gathers axe's violations for each.
+ * `ready` asserts the fixture's own data is on the page, since an audit of canned content proves nothing.
+ */
+export async function auditEverywhere(page: Page, path: string, ready: (page: Page) => Promise<void>): Promise<void> {
+  for (const theme of themes) {
+    for (const width of [1440, 390] as const) {
+      await setTheme(page, theme);
+      await page.setViewportSize(viewports[width]);
+      await page.goto('about:blank');
+      await page.goto(path);
+      await ready(page);
+      expect(await backgroundToken(page), `the ${theme} theme's tokens are in force at ${width}`).toBe(tokenBackground[theme]);
+      expect.soft(await axeViolations(page), `axe, ${theme} at ${width}`).toEqual([]);
+    }
+  }
+}
+
+/** One cell of the matrix table: its text, whitespace collapsed, and every link's href in it. */
+export interface Cell {
+  text: string;
+  links: { text: string; href: string }[];
+}
+
+/** The matrix table as rows keyed by column header (the header's text up to its first comma: "Tests, at the node" is "Tests"). */
+export async function readMatrix(page: Page): Promise<{ headers: string[]; rows: Record<string, Cell>[] }> {
+  const table = region(page, 'matrix-table').locator('table').first();
+  // No table on the page reads as no rows, so a caller's assertion fails rather than waiting on a missing element.
+  if ((await table.count()) === 0) return { headers: [], rows: [] };
+  return table.evaluate((table) => {
+      const clean = (s: string | null): string => (s ?? '').replace(/\s+/g, ' ').trim();
+      const headers = Array.from(table.querySelectorAll('thead th')).map((th) => clean(th.textContent).split(',')[0] ?? '');
+      const rows = Array.from(table.querySelectorAll('tbody tr')).map((tr) => {
+        const row: Record<string, { text: string; links: { text: string; href: string }[] }> = {};
+        Array.from(tr.querySelectorAll('th, td')).forEach((cell, i) => {
+          row[headers[i] ?? `#${i}`] = {
+            text: clean(cell.textContent),
+            links: Array.from(cell.querySelectorAll('a')).map((a) => ({ text: clean(a.textContent), href: a.getAttribute('href') ?? '' })),
+          };
+        });
+        return row;
+      });
+      return { headers, rows };
+    });
+}
+
+/** The rule IDs of the matrix rows on show, in order: each row's Rule cell starts with its ID. */
+export async function matrixRuleIds(page: Page): Promise<string[]> {
+  const { rows } = await readMatrix(page);
+  return rows.map((row) => (row['Rule']?.text ?? '').split(' ')[0] ?? '');
+}
diff --git a/tests/web/e2e/U1/support/parity.ts b/tests/web/e2e/U1/support/parity.ts
new file mode 100644
index 00000000..06c6008e
--- /dev/null
+++ b/tests/web/e2e/U1/support/parity.ts
@@ -0,0 +1,100 @@
+// Parity with U1's derived reference (docs/ui/derived/U1/), the built routes served on the design fixture
+// (docs/ui/fixture/), so both sides read the same data. Structure only: the tagged regions in order, the catalogued
+// components in each, the shell, the title and the navigation, and tokens in place of literal colours. The same
+// checks as U0b's parity (tests/web/e2e/U0b/support/parity.ts), against U1's references. Parity tests are the only
+// ones, with reachability, that may pass at the stub.
+import { expect } from '@playwright/test';
+import type { Page } from '@playwright/test';
+import { serveTrace, setTheme, themes, viewports } from '../../U0b/support/app';
+import { designFixtureDir } from '../../U0b/support/trail';
+import { route } from './app';
+import { literalColours, readBuilt, readReference, regionNamed, regionOrder } from './reference';
+import type { Structure } from './reference';
+
+export interface Screen {
+  label: string;
+  screen: string;
+  state: string;
+  path: string;
+}
+
+// Each reference's own data in the design fixture: the populated rule page is GET-1 (build/F2), the long-content one
+// COULD-2 (build/F3); the populated node page is build/F3, the git-only one build/F0a; the commit page is 3a092b0.
+export const overview: Screen = { label: 'overview', screen: 'overview', state: 'populated', path: route.overview };
+export const matrix: Screen = { label: 'requirements matrix', screen: 'matrix', state: 'populated', path: route.matrix };
+export const rule: Screen = { label: 'rule page (GET-1)', screen: 'rule', state: 'populated', path: route.rule('GET-1') };
+export const ruleLong: Screen = { label: 'rule page (COULD-2, the longest trail)', screen: 'rule', state: 'long-content', path: route.rule('COULD-2') };
+export const node: Screen = { label: 'node page (build/F3)', screen: 'node', state: 'populated', path: route.node('build', 'F3') };
+export const gitOnlyNode: Screen = { label: 'node page (build/F0a, git-only)', screen: 'node', state: 'git-only', path: route.node('build', 'F0a') };
+export const commit: Screen = {
+  label: 'commit page (3a092b0)',
+  screen: 'commit',
+  state: 'populated',
+  path: route.commit('3a092b06f4691f5cb5ee8ed117d4e755e2095545'),
+};
+
+async function open(page: Page, s: Screen): Promise<void> {
+  await serveTrace(page, designFixtureDir);
+  await setTheme(page, 'light');
+  await page.setViewportSize(viewports[1440]);
+  await page.goto(s.path);
+}
+
+function shellOf(s: Structure): Record<string, unknown> {
+  return {
+    title: s.title,
+    shell: s.shell,
+    navLinks: s.navLinks,
+    navNotBuilt: s.navNotBuilt,
+    navCurrent: s.navCurrent,
+    tabCurrent: s.tabCurrent,
+  };
+}
+
+function unbuiltComps(s: Structure): [string, string[]][] {
+  return s.regions.filter((r) => !r.built).map((r) => [r.slug, r.comps]);
+}
+
+/** Every region of the reference, in its order, with its data-req; the unbuilt ones as the not-built-yet pattern. */
+export async function expectRegionsInOrder(page: Page, s: Screen): Promise<void> {
+  const reference = await readReference(page.context(), s.screen, s.state);
+  await open(page, s);
+  await expect
+    .poll(async () => {
+      const built = await readBuilt(page, reference);
+      return { order: regionOrder(built), unbuilt: unbuiltComps(built) };
+    })
+    .toEqual({ order: regionOrder(reference), unbuilt: unbuiltComps(reference) });
+}
+
+/** One region of the reference, with its data-req and the catalogued components inside it. */
+export async function expectRegionComponents(page: Page, s: Screen, slug: string): Promise<void> {
+  const reference = await readReference(page.context(), s.screen, s.state);
+  const wanted = regionNamed(reference, slug);
+  expect(wanted, `the reference has region ${slug}`).toBeDefined();
+  await open(page, s);
+  await expect
+    .poll(async () => {
+      const found = regionNamed(await readBuilt(page, reference), slug);
+      return found ? { req: found.req, comps: found.comps } : null;
+    })
+    .toEqual({ req: wanted?.req, comps: wanted?.comps });
+}
+
+/** The shell's components, the primary nav (links, not-built entries, the current one), the current tab, the title. */
+export async function expectShell(page: Page, s: Screen): Promise<void> {
+  const reference = await readReference(page.context(), s.screen, s.state);
+  await open(page, s);
+  await expect.poll(async () => shellOf(await readBuilt(page, reference))).toEqual(shellOf(reference));
+}
+
+/** No colour on the page from a literal: the screen's styles, inline styles and SVG paint use tokens only. */
+export async function expectTokensOnly(page: Page, s: Screen): Promise<void> {
+  const reference = await readReference(page.context(), s.screen, s.state);
+  await open(page, s);
+  await expect.poll(async () => (await readBuilt(page, reference)).regions.length).toBe(reference.regions.length);
+  for (const theme of themes) {
+    await setTheme(page, theme);
+    expect.soft(await page.evaluate(literalColours), `literal colours, ${theme}`).toEqual([]);
+  }
+}
