diff --git a/tests/web/unit/compiler/nav-1.test.ts b/tests/web/unit/compiler/nav-1.test.ts
new file mode 100644
index 00000000..87137322
--- /dev/null
+++ b/tests/web/unit/compiler/nav-1.test.ts
@@ -0,0 +1,93 @@
+// @vitest-environment node
+// NAV-1 · Overview answers the question first. The landing screen states, from the data: rules built / total, tests
+// passing, nodes done, attempts and FAILs taken, human decisions recorded, each figure linked to its source. The
+// compiler holds the values each figure is counted from, and where each was read (docs/ui/derived/U1/overview/
+// screen.json, "receipt figures": rules[*].status, rules[*].matrix.tests, rules[*].matrix.source, nodes[*].status and
+// attempt, plans[*].source, verdicts[*].verdict, decisions[*].kind). On the `rules` fixture trail, whose README
+// gives every figure: 3 of 5 rules built, 2 of 5 pass in full, 2 of 4 nodes done, 1 of 2 looped nodes took more than
+// one attempt, 1 of 4 verdicts FAIL, 2 human decisions.
+import { afterAll, beforeAll, describe, expect, test } from 'vitest';
+import { replayTrail, run, SLOW, thrown } from './support/trail';
+import type { Run, Trail } from './support/trail';
+import { DAG_FILE, decisionsOf, F1_LOOP, MATRIX_FILE, nodesOf, plansOf, ruleOf, RULES, verdictsOf } from './support/rules';
+
+let trail: Trail;
+let r: Run;
+beforeAll(() => {
+  trail = replayTrail(RULES);
+  r = run(trail.root);
+}, SLOW);
+afterAll(() => trail?.cleanup());
+
+describe('rules built and tests passing', () => {
+  test('NAV-1 · rules built: SELL-1, SELL-2 and GET-1, each with a node and a test, are built', () => {
+    expect(r.error, thrown(r)).toBeUndefined();
+    expect(['SELL-1', 'SELL-2', 'GET-1'].map((id) => [id, ruleOf(r, id)?.status ?? null])).toEqual([
+      ['SELL-1', 'built'],
+      ['SELL-2', 'built'],
+      ['GET-1', 'built'],
+    ]);
+  });
+
+  test("NAV-1 · tests passing: SELL-1 and SELL-2 carry their matrix row's counts, 2/2 and 3/3", () => {
+    expect(r.error, thrown(r)).toBeUndefined();
+    expect(ruleOf(r, 'SELL-1')?.matrix?.tests ?? null).toEqual({ pass: 2, total: 2, raw: '2/2' });
+    expect(ruleOf(r, 'SELL-2')?.matrix?.tests ?? null).toEqual({ pass: 3, total: 3, raw: '3/3' });
+  });
+
+  test('NAV-1 · the rules-built and tests-passing figures link to the matrix row each count was read from', () => {
+    expect(r.error, thrown(r)).toBeUndefined();
+    // rules/trail/docs/trace/requirements-matrix.md: SELL-1 is line 6, SELL-2 line 7, GET-1 line 8.
+    expect(['SELL-1', 'SELL-2', 'GET-1'].map((id) => [id, ruleOf(r, id)?.matrix?.source ?? null])).toEqual([
+      ['SELL-1', { file: MATRIX_FILE, line: 6 }],
+      ['SELL-2', { file: MATRIX_FILE, line: 7 }],
+      ['GET-1', { file: MATRIX_FILE, line: 8 }],
+    ]);
+  });
+});
+
+describe('nodes done and attempts taken', () => {
+  test("NAV-1 · nodes done and attempts: each node's owner, status and attempt, as the plan DAG gives them", () => {
+    expect(r.error, thrown(r)).toBeUndefined();
+    // Done: F0a and F1 (2 of 4). Looped (owner loop, started): F1 at attempt 2 and F2 at 1; F0a is David's, F3 at 0.
+    expect(nodesOf(r).map((n) => [n.plan, n.id, n.owner ?? null, n.status ?? null, n.attempt ?? null])).toEqual([
+      ['build', 'F0a', 'david', 'done', 0],
+      ['build', 'F1', 'loop', 'done', 2],
+      ['build', 'F2', 'loop', 'in_progress', 1],
+      ['build', 'F3', 'loop', 'pending', 0],
+    ]);
+  });
+
+  test('NAV-1 · the nodes-done and attempts figures link to the plan DAG they were read from', () => {
+    expect(r.error, thrown(r)).toBeUndefined();
+    expect(plansOf(r).map((p) => [p.id, p.source ?? null])).toEqual([['build', DAG_FILE]]);
+  });
+});
+
+describe('FAILs taken', () => {
+  test("NAV-1 · FAILs taken: F1's four verdicts, one FAIL, each with its round, agent and verdict file", () => {
+    expect(r.error, thrown(r)).toBeUndefined();
+    const shown = verdictsOf(r)
+      .map((v) => [v.plan, v.node, v.round ?? null, v.agent ?? null, v.verdict ?? null, v.file ?? null])
+      .sort((a, b) => String(a[5]).localeCompare(String(b[5])));
+    expect(shown).toEqual([
+      ['build', 'F1', 'A1', 'reviewer', 'FAIL', 'docs/trace/build/F1/verdicts/A1-reviewer.json'],
+      ['build', 'F1', 'A1', 'security', 'PASS', 'docs/trace/build/F1/verdicts/A1-security.json'],
+      ['build', 'F1', 'A2', 'reviewer', 'PASS', 'docs/trace/build/F1/verdicts/A2-reviewer.json'],
+      ['build', 'F1', 'A2', 'security', 'PASS', 'docs/trace/build/F1/verdicts/A2-security.json'],
+    ]);
+  });
+});
+
+describe('human decisions recorded', () => {
+  test("NAV-1 · human decisions: F1's pause 1 and its sign-off, each at its loop.jsonl line; F2 has none", () => {
+    expect(r.error, thrown(r)).toBeUndefined();
+    // rules/trail/docs/trace/build/F1/loop.jsonl: pause1 is line 5, signoff(c9) line 18. Gates, verdicts, attempt++
+    // and pr(10) are not human decisions; F2's loop records none.
+    const shown = decisionsOf(r).map((d) => [d.kind, d.plan ?? null, d.node ?? null, d.when ?? null, d.evidence ?? null]);
+    expect(shown).toEqual([
+      ['pause1', 'build', 'F1', '2026-10-16T13:20:00Z', { file: F1_LOOP, line: 5 }],
+      ['signoff', 'build', 'F1', '2026-10-18T10:00:00Z', { file: F1_LOOP, line: 18 }],
+    ]);
+  });
+});
diff --git a/tests/web/unit/compiler/support/rules.ts b/tests/web/unit/compiler/support/rules.ts
new file mode 100644
index 00000000..08554b5b
--- /dev/null
+++ b/tests/web/unit/compiler/support/rules.ts
@@ -0,0 +1,124 @@
+// The `rules` fixture trail (tests/web/fixtures/trails/rules/README.md) for U1's compiler tests (NAV-1, RULE-2,
+// DATA-4): the trace.json fields the overview, the matrix and the rule page read, in the design fixture's shapes
+// (docs/ui/fixture/trace.json; each screen's fields in docs/ui/derived/U1/<screen>/screen.json), and the fixture's
+// own facts (each commit's id and date in rules/commits.json).
+import { readFileSync } from 'node:fs';
+import { join } from 'node:path';
+import { fixturesDir } from './trail';
+import type { Run, Trail } from './trail';
+
+export const RULES = 'rules';
+export const MATRIX_FILE = 'docs/trace/requirements-matrix.md';
+export const DAG_FILE = 'docs/plans/active/build.dag.yaml';
+export const F1_LOOP = 'docs/trace/build/F1/loop.jsonl';
+export const F2_README = 'docs/trace/build/F2/README.md';
+
+/** The five reasons rules/trail/docs/trace/build/F2/README.md gives under "## Completeness", in its order. */
+export const F2_REASONS = [
+  'rule GET-1 has no red commit before its green commit',
+  'rule GET-1 has no QA step',
+  'gate.red is not ok',
+  'gate.green is missing',
+  'gate.integrate is missing',
+];
+export const F2_LABEL = `TRAIL INCOMPLETE: ${F2_REASONS.join('; ')}`;
+
+/** A rule's requirements-matrix row, as the design fixture holds it (rules[*].matrix). Every field optional. */
+export interface MatrixOut {
+  plan?: string | null;
+  node?: string | null;
+  tests?: { pass?: number | null; total?: number | null; raw?: string | null } | null;
+  red?: string | null;
+  green?: string | null;
+  refactor?: string | null;
+  qaStep?: string | null;
+  signoff?: string | null;
+  pr?: string | null;
+  source?: { file?: string | null; line?: number | null } | null;
+}
+
+export interface RuleOut {
+  id?: string;
+  status?: string | null;
+  matrix?: MatrixOut | null;
+}
+
+export interface NodeOut {
+  plan?: string;
+  id?: string;
+  owner?: string | null;
+  status?: string | null;
+  attempt?: number | null;
+  completeness?: string | null;
+  completenessReasons?: string[];
+  trail?: boolean | null;
+}
+
+export interface PlanOut {
+  id?: string;
+  source?: string | null;
+}
+
+export interface CommitOut {
+  sha?: string;
+  short?: string;
+  plan?: string | null;
+  node?: string | null;
+  rule?: string[];
+  tdd?: string | null;
+  order?: number | null;
+  date?: string | null;
+}
+
+export interface VerdictOut {
+  plan?: string;
+  node?: string;
+  round?: string | null;
+  agent?: string | null;
+  verdict?: string | null;
+  file?: string | null;
+}
+
+export interface DecisionOut {
+  kind?: string;
+  plan?: string | null;
+  node?: string | null;
+  when?: string | null;
+  evidence?: { file?: string | null; line?: number | null } | null;
+}
+
+const list = <T>(r: Run, field: string): T[] => {
+  const value = r.trace?.[field];
+  return Array.isArray(value) ? (value as T[]) : [];
+};
+
+export const rulesOf = (r: Run): RuleOut[] => list<RuleOut>(r, 'rules');
+export const nodesOf = (r: Run): NodeOut[] => list<NodeOut>(r, 'nodes');
+export const plansOf = (r: Run): PlanOut[] => list<PlanOut>(r, 'plans');
+export const commitsOf = (r: Run): CommitOut[] => list<CommitOut>(r, 'commits');
+export const verdictsOf = (r: Run): VerdictOut[] => list<VerdictOut>(r, 'verdicts');
+export const decisionsOf = (r: Run): DecisionOut[] => list<DecisionOut>(r, 'decisions');
+
+export const ruleOf = (r: Run, id: string): RuleOut | undefined => rulesOf(r).find((rule) => rule.id === id);
+export const nodeOf = (r: Run, id: string): NodeOut | undefined => nodesOf(r).find((n) => n.plan === 'build' && n.id === id);
+
+/** A fixture commit's full SHA, by its id in rules/commits.json, or a marker no SHA equals. */
+export const shaOf = (trail: Trail, id: string): string => trail.shas[id] ?? `(no commit ${id})`;
+export const shortOf = (trail: Trail, id: string): string => shaOf(trail, id).slice(0, 7);
+
+/** The compiled commit a fixture commit id names. */
+export const commitOf = (r: Run, trail: Trail, id: string): CommitOut | undefined =>
+  commitsOf(r).find((c) => c.sha === shaOf(trail, id));
+
+/** The compiled commit a short SHA (as the matrix gives it) names, or undefined. */
+export const commitByShort = (r: Run, short: string | null | undefined): CommitOut | undefined =>
+  short ? commitsOf(r).find((c) => c.sha?.startsWith(short)) : undefined;
+
+/** Each fixture commit's id and the date it was made at, from rules/commits.json, in order. */
+export function fixtureDates(): { id: string; date: string }[] {
+  const spec = JSON.parse(readFileSync(join(fixturesDir, RULES, 'commits.json'), 'utf8')) as {
+    date: string;
+    commits: { id: string; date?: string }[];
+  };
+  return spec.commits.map((c) => ({ id: c.id, date: c.date ?? spec.date }));
+}

diff --git a/tests/web/unit/compiler/rule-2.test.ts b/tests/web/unit/compiler/rule-2.test.ts
new file mode 100644
index 00000000..04ad1f37
--- /dev/null
+++ b/tests/web/unit/compiler/rule-2.test.ts
@@ -0,0 +1,104 @@
+// @vitest-environment node
+// RULE-2 · Red before green, visibly. The rule page shows the red commit before the green one, with dates, and flags
+// any rule where that order doesn't hold. The compiler holds what that is drawn from (docs/ui/derived/U1/rule/
+// screen.json, the "red before green" region): each rule's red, green and refactor commits from its matrix row, each
+// commit's row in its node's walkthrough (commits[*].order, the rung's "#n") and the date git recorded for it. The
+// order is the commits' own, never re-sorted to look right. On the `rules` fixture trail: SELL-1's red c2 (row 2,
+// 2026-10-16) comes before its green c4 (row 4, 2026-10-17); GET-1's green c11 (row 2) came before its red c12 (row 3).
+import { afterAll, beforeAll, describe, expect, test } from 'vitest';
+import { replayTrail, run, SLOW, thrown } from './support/trail';
+import type { Run, Trail } from './support/trail';
+import { commitByShort, commitOf, fixtureDates, ruleOf, RULES, shortOf } from './support/rules';
+
+let trail: Trail;
+let r: Run;
+beforeAll(() => {
+  trail = replayTrail(RULES);
+  r = run(trail.root);
+}, SLOW);
+afterAll(() => trail?.cleanup());
+
+/** The UTC wall time of an instant, to the second: "2026-10-16T12:00:00". */
+const utcSecond = (iso: string): string => new Date(iso).toISOString().slice(0, 19);
+
+describe("each rule's red, green and refactor commits", () => {
+  test("RULE-2 · each rule's red, green and refactor are its matrix row's short SHAs; a dash or a blank is null", () => {
+    expect(r.error, thrown(r)).toBeUndefined();
+    const s = (id: string): string => shortOf(trail, id);
+    const shown = ['SELL-1', 'SELL-2', 'GET-1', 'CANCEL-1', 'CANCEL-2'].map((id) => {
+      const m = ruleOf(r, id)?.matrix;
+      return [id, m?.red ?? null, m?.green ?? null, m?.refactor ?? null];
+    });
+    // rules/trail/docs/trace/requirements-matrix.md, lines 6 to 10.
+    expect(shown).toEqual([
+      ['SELL-1', s('c2'), s('c4'), s('c5')],
+      ['SELL-2', s('c2'), s('c4'), null],
+      ['GET-1', s('c12'), s('c11'), null],
+      ['CANCEL-1', null, null, null],
+      ['CANCEL-2', null, null, null],
+    ]);
+  });
+});
+
+describe("each commit's place and date", () => {
+  test("RULE-2 · each commit's order is its row in its node's walkthrough, and a commit no walkthrough lists has none", () => {
+    expect(r.error, thrown(r)).toBeUndefined();
+    // rules/README.md, "Walkthrough rows": F1's c1 to c9 are rows 1 to 9, F2's c10 to c12 rows 1 to 3. c0 (F0a,
+    // git-only) is in no walkthrough.
+    const ids = ['c0', 'c1', 'c2', 'c3', 'c4', 'c5', 'c6', 'c7', 'c8', 'c9', 'c10', 'c11', 'c12'];
+    expect(ids.map((id) => [id, commitOf(r, trail, id)?.order ?? null])).toEqual([
+      ['c0', null],
+      ['c1', 1],
+      ['c2', 2],
+      ['c3', 3],
+      ['c4', 4],
+      ['c5', 5],
+      ['c6', 6],
+      ['c7', 7],
+      ['c8', 8],
+      ['c9', 9],
+      ['c10', 1],
+      ['c11', 2],
+      ['c12', 3],
+    ]);
+  });
+
+  test('RULE-2 · each commit carries the date git recorded for it, its own and not the compile time', () => {
+    expect(r.error, thrown(r)).toBeUndefined();
+    const dated = fixtureDates().map(({ id }) => {
+      const date = commitOf(r, trail, id)?.date ?? null;
+      return [id, date === null || Number.isNaN(Date.parse(date)) ? date : utcSecond(date)];
+    });
+    expect(dated).toEqual(fixtureDates().map(({ id, date }) => [id, utcSecond(date)]));
+  });
+
+  test('RULE-2 · a commit date is written in UTC: the fixture commits made at 12:00Z read 12:00', () => {
+    expect(r.error, thrown(r)).toBeUndefined();
+    // c2, c4 and c11 were made at 12:00 UTC (rules/README.md), so the page reads the same day in any zone it shows.
+    for (const id of ['c2', 'c4', 'c11']) {
+      expect(commitOf(r, trail, id)?.date ?? '(no date)', id).toMatch(/^\d{4}-\d{2}-\d{2}T12:00:00(?:\.0+)?(?:Z|\+00:00)$/);
+    }
+  });
+});
+
+describe('red before green, and the order that does not hold', () => {
+  test("RULE-2 · SELL-1's red c2 comes before its green c4: walkthrough rows 2 and 4, dated 2026-10-16 and 2026-10-17", () => {
+    expect(r.error, thrown(r)).toBeUndefined();
+    const m = ruleOf(r, 'SELL-1')?.matrix;
+    const red = commitByShort(r, m?.red);
+    const green = commitByShort(r, m?.green);
+    expect([red?.sha ?? null, red?.order ?? null, red?.date?.slice(0, 10) ?? null]).toEqual([trail.shas['c2'], 2, '2026-10-16']);
+    expect([green?.sha ?? null, green?.order ?? null, green?.date?.slice(0, 10) ?? null]).toEqual([trail.shas['c4'], 4, '2026-10-17']);
+  });
+
+  test("RULE-2 · GET-1's order does not hold: its matrix red c12 is row 3, after its green c11 at row 2, as committed", () => {
+    expect(r.error, thrown(r)).toBeUndefined();
+    const m = ruleOf(r, 'GET-1')?.matrix;
+    const red = commitByShort(r, m?.red);
+    const green = commitByShort(r, m?.green);
+    // Both on F2's walkthrough; kept in the order they were made, not swapped to read red first.
+    expect([red?.sha ?? null, red?.node ?? null, red?.tdd ?? null, red?.order ?? null]).toEqual([trail.shas['c12'], 'F2', 'red', 3]);
+    expect([green?.sha ?? null, green?.node ?? null, green?.tdd ?? null, green?.order ?? null]).toEqual([trail.shas['c11'], 'F2', 'green', 2]);
